package ext

type Document struct {
	Version   string     `yaml:"version,omitempty"`
	Namespace string     `yaml:"namespace,omitempty"`
	Flags     []*Flag    `yaml:"flags,omitempty"`
	Segments  []*Segment `yaml:"segments,omitempty"`
}

type Flag struct {
	Key         string     `yaml:"key,omitempty"`
	Name        string     `yaml:"name,omitempty"`
	Type        string     `yaml:"type,omitempty"`
	Description string     `yaml:"description,omitempty"`
	Enabled     bool       `yaml:"enabled"`
	Variants    []*Variant `yaml:"variants,omitempty"`
	Rules       []*Rule    `yaml:"rules,omitempty"`
	Rollouts    []*Rollout `yaml:"rollouts,omitempty"`
}

type Variant struct {
	Key         string      `yaml:"key,omitempty"`
	Name        string      `yaml:"name,omitempty"`
	Description string      `yaml:"description,omitempty"`
	Attachment  interface{} `yaml:"attachment,omitempty"`
}

type Rule struct {
	SegmentKey      string          `yaml:"segment,omitempty"`
	Rank            uint            `yaml:"rank,omitempty"`
	SegmentKeys     []string        `yaml:"segments,omitempty"`
	SegmentOperator string          `yaml:"operator,omitempty"`
	Distributions   []*Distribution `yaml:"distributions,omitempty"`
}

type Distribution struct {
	VariantKey string  `yaml:"variant,omitempty"`
	Rollout    float32 `yaml:"rollout,omitempty"`
}

type Rollout struct {
	Description string         `yaml:"description,omitempty"`
	Segment     *SegmentRule   `yaml:"segment,omitempty"`
	Threshold   *ThresholdRule `yaml:"threshold,omitempty"`
}

type SegmentRule struct {
	Key      string   `yaml:"key,omitempty"`
	Keys     []string `yaml:"keys,omitempty"`
	Operator string   `yaml:"operator,omitempty"`
	Value    bool     `yaml:"value,omitempty"`
}

type ThresholdRule struct {
	Percentage float32 `yaml:"percentage,omitempty"`
	Value      bool    `yaml:"value,omitempty"`
}

type Segment struct {
	Key         string        `yaml:"key,omitempty"`
	Name        string        `yaml:"name,omitempty"`
	Description string        `yaml:"description,omitempty"`
	Constraints []*Constraint `yaml:"constraints,omitempty"`
	MatchType   string        `yaml:"match_type,omitempty"`
}

type Constraint struct {
	Type        string `yaml:"type,omitempty"`
	Property    string `yaml:"property,omitempty"`
	Operator    string `yaml:"operator,omitempty"`
	Value       string `yaml:"value,omitempty"`
	Description string `yaml:"description,omitempty"`
}
package ext

import (
	"context"
	"encoding/json"
	"fmt"
	"io"

	"github.com/blang/semver/v4"
	"go.flipt.io/flipt/rpc/flipt"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	"gopkg.in/yaml.v2"
)

type Creator interface {
	GetNamespace(context.Context, *flipt.GetNamespaceRequest) (*flipt.Namespace, error)
	CreateNamespace(context.Context, *flipt.CreateNamespaceRequest) (*flipt.Namespace, error)
	CreateFlag(context.Context, *flipt.CreateFlagRequest) (*flipt.Flag, error)
	CreateVariant(context.Context, *flipt.CreateVariantRequest) (*flipt.Variant, error)
	CreateSegment(context.Context, *flipt.CreateSegmentRequest) (*flipt.Segment, error)
	CreateConstraint(context.Context, *flipt.CreateConstraintRequest) (*flipt.Constraint, error)
	CreateRule(context.Context, *flipt.CreateRuleRequest) (*flipt.Rule, error)
	CreateDistribution(context.Context, *flipt.CreateDistributionRequest) (*flipt.Distribution, error)
	CreateRollout(context.Context, *flipt.CreateRolloutRequest) (*flipt.Rollout, error)
}

type Importer struct {
	creator   Creator
	namespace string
	createNS  bool
}

type ImportOpt func(*Importer)

func WithNamespace(ns string) ImportOpt {
	return func(i *Importer) {
		i.namespace = ns
	}
}

func WithCreateNamespace() ImportOpt {
	return func(i *Importer) {
		i.createNS = true
	}
}

func NewImporter(store Creator, opts ...ImportOpt) *Importer {
	i := &Importer{
		creator: store,
	}

	for _, opt := range opts {
		opt(i)
	}

	return i
}

func (i *Importer) Import(ctx context.Context, r io.Reader) (err error) {
	var (
		dec = yaml.NewDecoder(r)
		doc = new(Document)
	)

	if err := dec.Decode(doc); err != nil {
		return fmt.Errorf("unmarshalling document: %w", err)
	}

	v := latestVersion
	if doc.Version != "" {
		v, err = semver.ParseTolerant(doc.Version)
		if err != nil {
			return fmt.Errorf("parsing document version: %w", err)
		}

		var found bool
		for _, sv := range supportedVersions {
			if found = sv.EQ(v); found {
				break
			}
		}

		if !found {
			return fmt.Errorf("unsupported version: %s", doc.Version)
		}
	}

	// check if document namespace matches cli namespace if both are set
	if doc.Namespace != "" && i.namespace != "" && doc.Namespace != i.namespace {
		return fmt.Errorf("namespace mismatch: namespaces must match in file and args if both provided: %s != %s", doc.Namespace, i.namespace)
	}

	// prefer document namespace over cli namespace, but use cli namespace if
	// document namespace is empty
	var namespace = doc.Namespace
	if namespace == "" {
		namespace = i.namespace
	}

	if i.createNS && namespace != "" && namespace != flipt.DefaultNamespace {
		_, err := i.creator.GetNamespace(ctx, &flipt.GetNamespaceRequest{
			Key: namespace,
		})

		if status.Code(err) != codes.NotFound {
			return err
		}

		_, err = i.creator.CreateNamespace(ctx, &flipt.CreateNamespaceRequest{
			Key:  namespace,
			Name: namespace,
		})
		if err != nil {
			return err
		}
	}

	var (
		// map flagKey => *flag
		createdFlags = make(map[string]*flipt.Flag)
		// map segmentKey => *segment
		createdSegments = make(map[string]*flipt.Segment)
		// map flagKey:variantKey => *variant
		createdVariants = make(map[string]*flipt.Variant)
	)

	// create flags/variants
	for _, f := range doc.Flags {
		if f == nil {
			continue
		}

		req := &flipt.CreateFlagRequest{
			Key:          f.Key,
			Name:         f.Name,
			Description:  f.Description,
			Enabled:      f.Enabled,
			NamespaceKey: namespace,
		}

		// support explicitly setting flag type from 1.1
		if f.Type != "" {
			if err := ensureFieldSupported("flag.type", semver.Version{
				Major: 1,
				Minor: 1,
			}, v); err != nil {
				return err
			}

			req.Type = flipt.FlagType(flipt.FlagType_value[f.Type])
		}

		flag, err := i.creator.CreateFlag(ctx, req)
		if err != nil {
			return fmt.Errorf("creating flag: %w", err)
		}

		for _, v := range f.Variants {
			if v == nil {
				continue
			}

			var out []byte

			if v.Attachment != nil {
				converted := convert(v.Attachment)
				out, err = json.Marshal(converted)
				if err != nil {
					return fmt.Errorf("marshalling attachment: %w", err)
				}
			}

			variant, err := i.creator.CreateVariant(ctx, &flipt.CreateVariantRequest{
				FlagKey:      f.Key,
				Key:          v.Key,
				Name:         v.Name,
				Description:  v.Description,
				Attachment:   string(out),
				NamespaceKey: namespace,
			})

			if err != nil {
				return fmt.Errorf("creating variant: %w", err)
			}

			createdVariants[fmt.Sprintf("%s:%s", flag.Key, variant.Key)] = variant
		}

		createdFlags[flag.Key] = flag
	}

	// create segments/constraints
	for _, s := range doc.Segments {
		if s == nil {
			continue
		}

		segment, err := i.creator.CreateSegment(ctx, &flipt.CreateSegmentRequest{
			Key:          s.Key,
			Name:         s.Name,
			Description:  s.Description,
			MatchType:    flipt.MatchType(flipt.MatchType_value[s.MatchType]),
			NamespaceKey: namespace,
		})

		if err != nil {
			return fmt.Errorf("creating segment: %w", err)
		}

		for _, c := range s.Constraints {
			if c == nil {
				continue
			}

			_, err := i.creator.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
				SegmentKey:   s.Key,
				Type:         flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),
				Property:     c.Property,
				Operator:     c.Operator,
				Value:        c.Value,
				NamespaceKey: namespace,
			})

			if err != nil {
				return fmt.Errorf("creating constraint: %w", err)
			}
		}

		createdSegments[segment.Key] = segment
	}

	// create rules/distributions
	for _, f := range doc.Flags {
		if f == nil {
			continue
		}

		// loop through rules
		for idx, r := range f.Rules {
			if r == nil {
				continue
			}

			// support implicit rank from version >=1.1
			rank := int32(r.Rank)
			if rank == 0 && v.GE(semver.Version{Major: 1, Minor: 1}) {
				rank = int32(idx) + 1
			}

			fcr := &flipt.CreateRuleRequest{
				FlagKey:         f.Key,
				Rank:            rank,
				NamespaceKey:    namespace,
				SegmentOperator: flipt.SegmentOperator(flipt.SegmentOperator_value[r.SegmentOperator]),
			}

			if len(r.SegmentKeys) > 0 && r.SegmentKey != "" {
				return fmt.Errorf("rule %s/%s/%d cannot have both segment and segments",
					namespace,
					f.Key,
					idx,
				)
			}

			if r.SegmentKey != "" {
				fcr.SegmentKey = r.SegmentKey
			} else if len(r.SegmentKeys) > 0 {
				// support explicitly setting only "segments" on rules from 1.2
				if err := ensureFieldSupported("flag.rules[*].segments", semver.Version{
					Major: 1,
					Minor: 2,
				}, v); err != nil {
					return err
				}
				fcr.SegmentKeys = r.SegmentKeys
			}

			rule, err := i.creator.CreateRule(ctx, fcr)

			if err != nil {
				return fmt.Errorf("creating rule: %w", err)
			}

			for _, d := range r.Distributions {
				if d == nil {
					continue
				}

				variant, found := createdVariants[fmt.Sprintf("%s:%s", f.Key, d.VariantKey)]
				if !found {
					return fmt.Errorf("finding variant: %s; flag: %s", d.VariantKey, f.Key)
				}

				_, err := i.creator.CreateDistribution(ctx, &flipt.CreateDistributionRequest{
					FlagKey:      f.Key,
					RuleId:       rule.Id,
					VariantId:    variant.Id,
					Rollout:      d.Rollout,
					NamespaceKey: namespace,
				})

				if err != nil {
					return fmt.Errorf("creating distribution: %w", err)
				}
			}
		}

		// support explicitly setting flag type from 1.1
		if len(f.Rollouts) > 0 {
			if err := ensureFieldSupported("flag.rollouts", semver.Version{
				Major: 1,
				Minor: 1,
			}, v); err != nil {
				return err
			}

			for idx, r := range f.Rollouts {
				if r.Segment != nil && r.Threshold != nil {
					return fmt.Errorf(`rollout "%s/%s/%d" cannot have both segment and percentage rule`,
						namespace,
						f.Key,
						idx,
					)
				}

				req := &flipt.CreateRolloutRequest{
					NamespaceKey: namespace,
					FlagKey:      f.Key,
					Description:  r.Description,
					Rank:         int32(idx + 1),
				}

				if r.Segment != nil {
					frs := &flipt.RolloutSegment{
						Value:      r.Segment.Value,
						SegmentKey: r.Segment.Key,
					}

					if len(r.Segment.Keys) > 0 && r.Segment.Key != "" {
						return fmt.Errorf("rollout %s/%s/%d cannot have both segment.keys and segment.key",
							namespace,
							f.Key,
							idx,
						)
					}

					// support explicitly setting only "keys" on rules from 1.2
					if len(r.Segment.Keys) > 0 {
						if err := ensureFieldSupported("flag.rollouts[*].segment.keys", semver.Version{
							Major: 1,
							Minor: 2,
						}, v); err != nil {
							return err
						}

						frs.SegmentKeys = r.Segment.Keys
					}

					frs.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[r.Segment.Operator])

					req.Rule = &flipt.CreateRolloutRequest_Segment{
						Segment: frs,
					}
				} else if r.Threshold != nil {
					req.Rule = &flipt.CreateRolloutRequest_Threshold{
						Threshold: &flipt.RolloutThreshold{
							Percentage: r.Threshold.Percentage,
							Value:      r.Threshold.Value,
						},
					}
				}

				if _, err := i.creator.CreateRollout(ctx, req); err != nil {
					return fmt.Errorf("creating rollout: %w", err)
				}
			}
		}
	}

	return nil
}

// convert converts each encountered map[interface{}]interface{} to a map[string]interface{} value.
// This is necessary because the json library does not support map[interface{}]interface{} values which nested
// maps get unmarshalled into from the yaml library.
func convert(i interface{}) interface{} {
	switch x := i.(type) {
	case map[interface{}]interface{}:
		m := map[string]interface{}{}
		for k, v := range x {
			if sk, ok := k.(string); ok {
				m[sk] = convert(v)
			}
		}
		return m
	case []interface{}:
		for i, v := range x {
			x[i] = convert(v)
		}
	}
	return i
}

func ensureFieldSupported(field string, expected, have semver.Version) error {
	if have.LT(expected) {
		return fmt.Errorf("%s is supported in version >=%s, found %s",
			field,
			versionString(expected),
			versionString(have))
	}

	return nil
}
package ext

import (
	"context"
	"encoding/json"
	"fmt"
	"io"

	"github.com/blang/semver/v4"
	"go.flipt.io/flipt/rpc/flipt"
	"gopkg.in/yaml.v2"
)

const (
	defaultBatchSize = 25
)

var (
	latestVersion     = semver.Version{Major: 1, Minor: 2}
	supportedVersions = semver.Versions{
		{Major: 1},
		latestVersion,
	}
)

type Lister interface {
	ListFlags(context.Context, *flipt.ListFlagRequest) (*flipt.FlagList, error)
	ListSegments(context.Context, *flipt.ListSegmentRequest) (*flipt.SegmentList, error)
	ListRules(context.Context, *flipt.ListRuleRequest) (*flipt.RuleList, error)
	ListRollouts(context.Context, *flipt.ListRolloutRequest) (*flipt.RolloutList, error)
}

type Exporter struct {
	store     Lister
	batchSize int32
	namespace string
}

func NewExporter(store Lister, namespace string) *Exporter {
	return &Exporter{
		store:     store,
		batchSize: defaultBatchSize,
		namespace: namespace,
	}
}

// We currently only do minor bumps and print out just major.minor
func versionString(v semver.Version) string {
	return fmt.Sprintf("%d.%d", v.Major, v.Minor)
}

func (e *Exporter) Export(ctx context.Context, w io.Writer) error {
	var (
		enc       = yaml.NewEncoder(w)
		doc       = new(Document)
		batchSize = e.batchSize
	)

	doc.Version = versionString(latestVersion)
	doc.Namespace = e.namespace

	defer enc.Close()

	var (
		remaining = true
		nextPage  string
	)

	// export flags/variants in batches
	for batch := int32(0); remaining; batch++ {
		resp, err := e.store.ListFlags(
			ctx,
			&flipt.ListFlagRequest{
				NamespaceKey: e.namespace,
				PageToken:    nextPage,
				Limit:        batchSize,
			},
		)
		if err != nil {
			return fmt.Errorf("getting flags: %w", err)
		}

		flags := resp.Flags
		nextPage = resp.NextPageToken
		remaining = nextPage != ""

		for _, f := range flags {
			flag := &Flag{
				Key:         f.Key,
				Name:        f.Name,
				Type:        f.Type.String(),
				Description: f.Description,
				Enabled:     f.Enabled,
			}

			// map variant id => variant key
			variantKeys := make(map[string]string)

			for _, v := range f.Variants {
				var attachment interface{}

				if v.Attachment != "" {
					if err := json.Unmarshal([]byte(v.Attachment), &attachment); err != nil {
						return fmt.Errorf("unmarshaling variant attachment: %w", err)
					}
				}

				flag.Variants = append(flag.Variants, &Variant{
					Key:         v.Key,
					Name:        v.Name,
					Description: v.Description,
					Attachment:  attachment,
				})

				variantKeys[v.Id] = v.Key
			}

			// export rules for flag
			resp, err := e.store.ListRules(
				ctx,
				&flipt.ListRuleRequest{
					NamespaceKey: e.namespace,
					FlagKey:      flag.Key,
				},
			)
			if err != nil {
				return fmt.Errorf("getting rules for flag %q: %w", flag.Key, err)
			}

			rules := resp.Rules
			for _, r := range rules {
				rule := &Rule{}
				if r.SegmentKey != "" {
					rule.SegmentKey = r.SegmentKey
				} else if len(r.SegmentKeys) > 0 {
					rule.SegmentKeys = r.SegmentKeys
				}

				if r.SegmentOperator == flipt.SegmentOperator_AND_SEGMENT_OPERATOR {
					rule.SegmentOperator = r.SegmentOperator.String()
				}

				for _, d := range r.Distributions {
					rule.Distributions = append(rule.Distributions, &Distribution{
						VariantKey: variantKeys[d.VariantId],
						Rollout:    d.Rollout,
					})
				}

				flag.Rules = append(flag.Rules, rule)
			}

			rollouts, err := e.store.ListRollouts(ctx, &flipt.ListRolloutRequest{
				NamespaceKey: e.namespace,
				FlagKey:      flag.Key,
			})
			if err != nil {
				return fmt.Errorf("getting rollout rules for flag %q: %w", flag.Key, err)
			}

			for _, r := range rollouts.Rules {
				rollout := Rollout{
					Description: r.Description,
				}

				switch rule := r.Rule.(type) {
				case *flipt.Rollout_Segment:
					rollout.Segment = &SegmentRule{
						Value: rule.Segment.Value,
					}

					if rule.Segment.SegmentKey != "" {
						rollout.Segment.Key = rule.Segment.SegmentKey
					} else if len(rule.Segment.SegmentKeys) > 0 {
						rollout.Segment.Keys = rule.Segment.SegmentKeys
					}

					if rule.Segment.SegmentOperator == flipt.SegmentOperator_AND_SEGMENT_OPERATOR {
						rollout.Segment.Operator = rule.Segment.SegmentOperator.String()
					}
				case *flipt.Rollout_Threshold:
					rollout.Threshold = &ThresholdRule{
						Percentage: rule.Threshold.Percentage,
						Value:      rule.Threshold.Value,
					}
				}

				flag.Rollouts = append(flag.Rollouts, &rollout)
			}

			doc.Flags = append(doc.Flags, flag)
		}
	}

	remaining = true
	nextPage = ""

	// export segments/constraints in batches
	for batch := int32(0); remaining; batch++ {
		resp, err := e.store.ListSegments(
			ctx,
			&flipt.ListSegmentRequest{
				NamespaceKey: e.namespace,
				PageToken:    nextPage,
				Limit:        batchSize,
			},
		)
		if err != nil {
			return fmt.Errorf("getting segments: %w", err)
		}

		segments := resp.Segments
		nextPage = resp.NextPageToken
		remaining = nextPage != ""

		for _, s := range segments {
			segment := &Segment{
				Key:         s.Key,
				Name:        s.Name,
				Description: s.Description,
				MatchType:   s.MatchType.String(),
			}

			for _, c := range s.Constraints {
				segment.Constraints = append(segment.Constraints, &Constraint{
					Type:        c.Type.String(),
					Property:    c.Property,
					Operator:    c.Operator,
					Value:       c.Value,
					Description: c.Description,
				})
			}

			doc.Segments = append(doc.Segments, segment)
		}
	}

	if err := enc.Encode(doc); err != nil {
		return fmt.Errorf("marshaling document: %w", err)
	}

	return nil
}

package fs

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"sort"
	"strconv"

	"github.com/gobwas/glob"
	"github.com/gofrs/uuid"
	errs "go.flipt.io/flipt/errors"
	"go.flipt.io/flipt/internal/ext"
	"go.flipt.io/flipt/internal/storage"
	"go.flipt.io/flipt/rpc/flipt"
	"go.uber.org/zap"
	"google.golang.org/protobuf/types/known/timestamppb"
	"gopkg.in/yaml.v3"
)

const (
	indexFile = ".flipt.yml"
	defaultNs = "default"
)

var (
	_                 storage.Store = (*storeSnapshot)(nil)
	ErrNotImplemented               = errors.New("not implemented")
)

// FliptIndex represents the structure of a well-known file ".flipt.yml"
// at the root of an FS.
type FliptIndex struct {
	Version string   `yaml:"version,omitempty"`
	Include []string `yaml:"include,omitempty"`
	Exclude []string `yaml:"exclude,omitempty"`
}

// storeSnapshot contains the structures necessary for serving
// flag state to a client.
type storeSnapshot struct {
	ns        map[string]*namespace
	evalDists map[string][]*storage.EvaluationDistribution
	now       *timestamppb.Timestamp
}

type namespace struct {
	resource     *flipt.Namespace
	flags        map[string]*flipt.Flag
	segments     map[string]*flipt.Segment
	rules        map[string]*flipt.Rule
	rollouts     map[string]*flipt.Rollout
	evalRules    map[string][]*storage.EvaluationRule
	evalRollouts map[string][]*storage.EvaluationRollout
}

func newNamespace(key, name string, created *timestamppb.Timestamp) *namespace {
	return &namespace{
		resource: &flipt.Namespace{
			Key:       key,
			Name:      name,
			CreatedAt: created,
			UpdatedAt: created,
		},
		flags:        map[string]*flipt.Flag{},
		segments:     map[string]*flipt.Segment{},
		rules:        map[string]*flipt.Rule{},
		rollouts:     map[string]*flipt.Rollout{},
		evalRules:    map[string][]*storage.EvaluationRule{},
		evalRollouts: map[string][]*storage.EvaluationRollout{},
	}
}

// snapshotFromFS is a convenience function for building a snapshot
// directly from an implementation of fs.FS using the list state files
// function to source the relevant Flipt configuration files.
func snapshotFromFS(logger *zap.Logger, fs fs.FS) (*storeSnapshot, error) {
	files, err := listStateFiles(logger, fs)
	if err != nil {
		return nil, err
	}

	logger.Debug("opening state files", zap.Strings("paths", files))

	var rds []io.Reader
	for _, file := range files {
		fi, err := fs.Open(file)
		if err != nil {
			return nil, err
		}

		defer fi.Close()
		rds = append(rds, fi)
	}

	return snapshotFromReaders(rds...)
}

// snapshotFromReaders constructs a storeSnapshot from the provided
// slice of io.Reader.
func snapshotFromReaders(sources ...io.Reader) (*storeSnapshot, error) {
	now := timestamppb.Now()
	s := storeSnapshot{
		ns: map[string]*namespace{
			defaultNs: newNamespace("default", "Default", now),
		},
		evalDists: map[string][]*storage.EvaluationDistribution{},
		now:       now,
	}

	for _, reader := range sources {
		doc := new(ext.Document)

		if err := yaml.NewDecoder(reader).Decode(doc); err != nil {
			return nil, err
		}

		// set namespace to default if empty in document
		if doc.Namespace == "" {
			doc.Namespace = "default"
		}

		if err := s.addDoc(doc); err != nil {
			return nil, err
		}

	}
	return &s, nil
}

func listStateFiles(logger *zap.Logger, source fs.FS) ([]string, error) {
	// This is the default variable + value for the FliptIndex. It will preserve its value if
	// a .flipt.yml can not be read for whatever reason.
	idx := FliptIndex{
		Version: "1.0",
		Include: []string{
			"**features.yml", "**features.yaml", "**.features.yml", "**.features.yaml",
		},
	}

	// Read index file
	inFile, err := source.Open(indexFile)
	if err == nil {
		if derr := yaml.NewDecoder(inFile).Decode(&idx); derr != nil {
			return nil, fmt.Errorf("yaml: %w", derr)
		}
	}

	if err != nil {
		if !errors.Is(err, fs.ErrNotExist) {
			return nil, err
		} else {
			logger.Debug("index file does not exist, defaulting...", zap.String("file", indexFile), zap.Error(err))
		}
	}

	var includes []glob.Glob
	for _, g := range idx.Include {
		glob, err := glob.Compile(g)
		if err != nil {
			return nil, fmt.Errorf("compiling include glob: %w", err)
		}

		includes = append(includes, glob)
	}

	filenames := make([]string, 0)
	if err := fs.WalkDir(source, ".", func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}

		if d.IsDir() {
			return nil
		}

		for _, glob := range includes {
			if glob.Match(path) {
				filenames = append(filenames, path)
				return nil
			}
		}

		return nil
	}); err != nil {
		return nil, err
	}

	if len(idx.Exclude) > 0 {
		var excludes []glob.Glob
		for _, g := range idx.Exclude {
			glob, err := glob.Compile(g)
			if err != nil {
				return nil, fmt.Errorf("compiling include glob: %w", err)
			}

			excludes = append(excludes, glob)
		}

	OUTER:
		for i := range filenames {
			for _, glob := range excludes {
				if glob.Match(filenames[i]) {
					filenames = append(filenames[:i], filenames[i+1:]...)
					continue OUTER
				}
			}
		}
	}

	return filenames, nil
}

func (ss *storeSnapshot) addDoc(doc *ext.Document) error {
	ns := ss.ns[doc.Namespace]
	if ns == nil {
		ns = newNamespace(doc.Namespace, doc.Namespace, ss.now)
	}

	evalDists := map[string][]*storage.EvaluationDistribution{}
	if len(ss.evalDists) > 0 {
		evalDists = ss.evalDists
	}

	for _, s := range doc.Segments {
		matchType := flipt.MatchType_value[s.MatchType]
		segment := &flipt.Segment{
			NamespaceKey: doc.Namespace,
			Name:         s.Name,
			Key:          s.Key,
			Description:  s.Description,
			MatchType:    flipt.MatchType(matchType),
			CreatedAt:    ss.now,
			UpdatedAt:    ss.now,
		}

		for _, constraint := range s.Constraints {
			constraintType := flipt.ComparisonType_value[constraint.Type]
			segment.Constraints = append(segment.Constraints, &flipt.Constraint{
				NamespaceKey: doc.Namespace,
				SegmentKey:   segment.Key,
				Id:           uuid.Must(uuid.NewV4()).String(),
				Operator:     constraint.Operator,
				Property:     constraint.Property,
				Type:         flipt.ComparisonType(constraintType),
				Value:        constraint.Value,
				Description:  constraint.Description,
				CreatedAt:    ss.now,
				UpdatedAt:    ss.now,
			})
		}

		ns.segments[segment.Key] = segment
	}

	for _, f := range doc.Flags {
		flagType := flipt.FlagType_value[f.Type]
		flag := &flipt.Flag{
			NamespaceKey: doc.Namespace,
			Key:          f.Key,
			Name:         f.Name,
			Description:  f.Description,
			Enabled:      f.Enabled,
			Type:         flipt.FlagType(flagType),
			CreatedAt:    ss.now,
			UpdatedAt:    ss.now,
		}

		for _, v := range f.Variants {
			attachment, err := json.Marshal(v.Attachment)
			if err != nil {
				return err
			}

			flag.Variants = append(flag.Variants, &flipt.Variant{
				Id:           uuid.Must(uuid.NewV4()).String(),
				NamespaceKey: doc.Namespace,
				Key:          v.Key,
				Name:         v.Name,
				Description:  v.Description,
				Attachment:   string(attachment),
				CreatedAt:    ss.now,
				UpdatedAt:    ss.now,
			})
		}

		ns.flags[f.Key] = flag

		evalRules := []*storage.EvaluationRule{}
		for i, r := range f.Rules {
			rank := int32(i + 1)
			rule := &flipt.Rule{
				NamespaceKey: doc.Namespace,
				Id:           uuid.Must(uuid.NewV4()).String(),
				FlagKey:      f.Key,
				SegmentKey:   r.SegmentKey,
				SegmentKeys:  r.SegmentKeys,
				Rank:         rank,
				CreatedAt:    ss.now,
				UpdatedAt:    ss.now,
			}

			evalRule := &storage.EvaluationRule{
				NamespaceKey: doc.Namespace,
				FlagKey:      f.Key,
				ID:           rule.Id,
				Rank:         rank,
			}

			var (
				segmentKeys = []string{}
				segments    = make(map[string]*storage.EvaluationSegment)
			)

			if rule.SegmentKey != "" {
				segmentKeys = append(segmentKeys, rule.SegmentKey)
			} else if len(rule.SegmentKeys) > 0 {
				segmentKeys = append(segmentKeys, rule.SegmentKeys...)
			}

			for _, segmentKey := range segmentKeys {
				segment := ns.segments[segmentKey]
				if segment == nil {
					return errs.ErrNotFoundf("segment %q in rule %d", segmentKey, rank)
				}

				evc := make([]storage.EvaluationConstraint, 0, len(segment.Constraints))
				for _, constraint := range segment.Constraints {
					evc = append(evc, storage.EvaluationConstraint{
						Operator: constraint.Operator,
						Property: constraint.Property,
						Type:     constraint.Type,
						Value:    constraint.Value,
					})
				}

				segments[segmentKey] = &storage.EvaluationSegment{
					SegmentKey:  segmentKey,
					MatchType:   segment.MatchType,
					Constraints: evc,
				}
			}

			segmentOperator := flipt.SegmentOperator_value[r.SegmentOperator]
			evalRule.SegmentOperator = flipt.SegmentOperator(segmentOperator)
			evalRule.Segments = segments

			evalRules = append(evalRules, evalRule)

			// Set segment operator on rule.
			rule.SegmentOperator = flipt.SegmentOperator(segmentOperator)

			for _, d := range r.Distributions {
				variant, found := findByKey(d.VariantKey, flag.Variants...)
				if !found {
					continue
				}

				id := uuid.Must(uuid.NewV4()).String()
				rule.Distributions = append(rule.Distributions, &flipt.Distribution{
					Id:        id,
					Rollout:   d.Rollout,
					RuleId:    rule.Id,
					VariantId: variant.Id,
					CreatedAt: ss.now,
					UpdatedAt: ss.now,
				})

				evalDists[evalRule.ID] = append(evalDists[evalRule.ID], &storage.EvaluationDistribution{
					ID:                id,
					Rollout:           d.Rollout,
					VariantID:         variant.Id,
					VariantKey:        variant.Key,
					VariantAttachment: variant.Attachment,
				})
			}

			ns.rules[rule.Id] = rule
		}

		ns.evalRules[f.Key] = evalRules

		evalRollouts := make([]*storage.EvaluationRollout, 0, len(f.Rollouts))
		for i, rollout := range f.Rollouts {
			rank := int32(i + 1)
			s := &storage.EvaluationRollout{
				NamespaceKey: doc.Namespace,
				Rank:         rank,
			}

			flagRollout := &flipt.Rollout{
				Id:           uuid.Must(uuid.NewV4()).String(),
				Rank:         rank,
				FlagKey:      f.Key,
				NamespaceKey: doc.Namespace,
				CreatedAt:    ss.now,
				UpdatedAt:    ss.now,
			}

			if rollout.Threshold != nil {
				s.Threshold = &storage.RolloutThreshold{
					Percentage: rollout.Threshold.Percentage,
					Value:      rollout.Threshold.Value,
				}
				s.RolloutType = flipt.RolloutType_THRESHOLD_ROLLOUT_TYPE

				flagRollout.Type = s.RolloutType
				flagRollout.Rule = &flipt.Rollout_Threshold{
					Threshold: &flipt.RolloutThreshold{
						Percentage: rollout.Threshold.Percentage,
						Value:      rollout.Threshold.Value,
					},
				}
			} else if rollout.Segment != nil {
				var (
					segmentKeys = []string{}
					segments    = make(map[string]*storage.EvaluationSegment)
				)

				if rollout.Segment.Key != "" {
					segmentKeys = append(segmentKeys, rollout.Segment.Key)
				} else if len(rollout.Segment.Keys) > 0 {
					segmentKeys = append(segmentKeys, rollout.Segment.Keys...)
				}

				for _, segmentKey := range segmentKeys {
					segment, ok := ns.segments[segmentKey]
					if !ok {
						return errs.ErrNotFoundf("segment %q not found", rollout.Segment.Key)
					}

					constraints := make([]storage.EvaluationConstraint, 0, len(segment.Constraints))
					for _, c := range segment.Constraints {
						constraints = append(constraints, storage.EvaluationConstraint{
							Operator: c.Operator,
							Property: c.Property,
							Type:     c.Type,
							Value:    c.Value,
						})
					}

					segments[segmentKey] = &storage.EvaluationSegment{
						SegmentKey:  segmentKey,
						MatchType:   segment.MatchType,
						Constraints: constraints,
					}
				}

				segmentOperator := flipt.SegmentOperator_value[rollout.Segment.Operator]

				s.Segment = &storage.RolloutSegment{
					Segments:        segments,
					SegmentOperator: flipt.SegmentOperator(segmentOperator),
					Value:           rollout.Segment.Value,
				}

				s.RolloutType = flipt.RolloutType_SEGMENT_ROLLOUT_TYPE

				frs := &flipt.RolloutSegment{
					Value:           rollout.Segment.Value,
					SegmentOperator: flipt.SegmentOperator(segmentOperator),
				}

				if len(segmentKeys) == 1 {
					frs.SegmentKey = segmentKeys[0]
				} else {
					frs.SegmentKeys = segmentKeys
				}

				flagRollout.Type = s.RolloutType
				flagRollout.Rule = &flipt.Rollout_Segment{
					Segment: frs,
				}
			}

			ns.rollouts[flagRollout.Id] = flagRollout

			evalRollouts = append(evalRollouts, s)
		}

		ns.evalRollouts[f.Key] = evalRollouts
	}

	ss.ns[doc.Namespace] = ns

	ss.evalDists = evalDists

	return nil
}

